    13	/**
    14	 * Translates the JSON scenario protocol into MHPCO operations and back.
    15	 * The protocol field names are binding; the premium rules live in
    16	 * {@link PremiumPolicy}.
    17	 */
    18	public class ClaimOfficeCli {
    19	
    20	    private static final ObjectMapper JSON = new ObjectMapper();
    21	
    22	    private final PremiumPolicy premiumPolicy = new PremiumPolicy();
    23	
    24	    public void run(InputStream scenario, PrintStream results) {
    25	        try {
    26	            JsonNode input = JSON.readTree(scenario);
    27	            Customer customer = new Customer(input.get("customer").get("yearsWithMHPCO").asInt());
    28	            ObjectNode output = JSON.createObjectNode();
    29	            ArrayNode resultsNode = output.putArray("results");
    30	            for (JsonNode step : input.get("steps")) {
    31	                resultsNode.addObject().put("premium", premiumPolicy.quote(customer, insuredItems(step)));
    32	            }
    33	            results.print(JSON.writeValueAsString(output));
    34	        } catch (IOException e) {
    35	            throw new UncheckedIOException(e);
    36	        }
    37	    }
    38	
    39	    private static List<InsuredItem> insuredItems(JsonNode quoteStep) {
    40	        List<InsuredItem> items = new ArrayList<>();
    41	        for (JsonNode item : quoteStep.get("items")) {
    42	            items.add(new InsuredItem(item.get("type").asText(),
    43	                    item.path("cursed").asBoolean(false),
    44	                    item.path("enchantment").asInt(0)));
    45	        }
    46	        return items;
    47	    }
    48	}
