     1	import java.math.BigDecimal;
     2	import java.math.RoundingMode;
     3	import java.util.List;
     4	
     5	/**
     6	 * The MHPCO premium rules: the two scopes of premium modifier, the processing
     7	 * fee, and rounding in the office's favor, applied to the base premium the
     8	 * {@link PriceList} states for the insured items.
     9	 *
    10	 * Intermediate amounts stay exact fractions; only the final premium is rounded.
    11	 */
    12	public class PremiumPolicy {
    13	
    14	    private static final BigDecimal CURSE_SURCHARGE_RATE = new BigDecimal("0.50");
    15	    private static final BigDecimal HIGH_ENCHANTMENT_SURCHARGE_RATE = new BigDecimal("0.30");
    16	    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
    17	    private static final BigDecimal FIRST_INSURANCE_SURCHARGE_RATE = new BigDecimal("0.10");
    18	    private static final BigDecimal LOYALTY_DISCOUNT_RATE = new BigDecimal("0.20");
    19	    private static final int LOYALTY_YEARS = 2;
    20	    private static final BigDecimal PROCESSING_FEE = new BigDecimal("5");
    21	
    22	    private final PriceList priceList = new PriceList();
    23	
    24	    /**
    25	     * The office charges both kinds of modifier on a base premium, never on each
    26	     * other: an item modifier on the affected item's own base premium, a
    27	     * policy-wide modifier on the policy base premium. So the two are summed
    28	     * alongside the base premium rather than compounded in sequence, and the
    29	     * processing fee is added at the very end.
    30	     */
    31	    public int quote(Customer customer, List<InsuredItem> insuredItems) {
    32	        BigDecimal policyBasePremium = priceList.policyBasePremium(insuredItems);
    33	        BigDecimal premium = policyBasePremium
    34	                .add(itemRiskSurcharges(insuredItems))
    35	                .add(policyWideModifiers(policyBasePremium, customer))
    36	                .add(PROCESSING_FEE);
    37	        return inOfficesFavor(premium);
    38	    }
    39	
    40	    /**
    41	     * Item-scope modifiers: each is charged on the base premium of the affected
    42	     * item alone, so a modifier on one item never touches another item's share
    43	     * of the policy.
    44	     *
    45	     * A curse and a high enchantment are separate risks, so an item carrying
    46	     * both is surcharged for both: the office charges them side by side on the
    47	     * same item base premium rather than letting the graver risk absorb the
    48	     * other.
    49	     */
    50	    private BigDecimal itemRiskSurcharges(List<InsuredItem> insuredItems) {
    51	        BigDecimal surcharges = BigDecimal.ZERO;
    52	        for (InsuredItem insuredItem : insuredItems) {
    53	            BigDecimal itemBasePremium = priceList.basePremium(insuredItem);
    54	            if (insuredItem.cursed()) {
    55	                surcharges = surcharges.add(itemBasePremium.multiply(CURSE_SURCHARGE_RATE));
    56	            }
    57	            if (isHighlyEnchanted(insuredItem)) {
    58	                surcharges = surcharges
    59	                        .add(itemBasePremium.multiply(HIGH_ENCHANTMENT_SURCHARGE_RATE));
    60	            }
    61	        }
    62	        return surcharges;
    63	    }
    64	
    65	    /** The office counts an item as highly enchanted from enchantment level 5 up. */
    66	    private static boolean isHighlyEnchanted(InsuredItem insuredItem) {
    67	        return insuredItem.enchantment() >= HIGH_ENCHANTMENT_LEVEL;
    68	    }
    69	
    70	    /**
    71	     * Policy-scope modifiers: each is charged on the policy base premium, the
    72	     * sum of all item base premiums. Every quote is a first insurance of the
    73	     * items it covers, whatever the customer's history.
    74	     */
    75	    private BigDecimal policyWideModifiers(BigDecimal policyBasePremium, Customer customer) {
    76	        return firstInsuranceSurcharge(policyBasePremium)
    77	                .subtract(loyaltyDiscount(policyBasePremium, customer));
    78	    }
    79	
    80	    /**
    81	     * Every quote is a first insurance of the items it covers, whatever the
    82	     * customer's history, so this surcharge is charged on every policy.
    83	     */
    84	    private static BigDecimal firstInsuranceSurcharge(BigDecimal policyBasePremium) {
    85	        return policyBasePremium.multiply(FIRST_INSURANCE_SURCHARGE_RATE);
    86	    }
    87	
    88	    /**
    89	     * The office rewards a long-standing customer -- one with 2 years of
    90	     * business with the MHPCO or more -- with a discount on the policy base
    91	     * premium. A newer customer earns nothing.
    92	     */
    93	    private static BigDecimal loyaltyDiscount(BigDecimal policyBasePremium, Customer customer) {
    94	        if (customer.yearsWithMHPCO() < LOYALTY_YEARS) {
    95	            return BigDecimal.ZERO;
    96	        }
    97	        return policyBasePremium.multiply(LOYALTY_DISCOUNT_RATE);
    98	    }
    99	
   100	    private int inOfficesFavor(BigDecimal premium) {
   101	        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
   102	    }
   103	}
